=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO with edge/level interrupts.
// Implements microarchitecture.md against interface_spec.md (eval case rtl/apb-gpio).
`default_nettype none

module apb_gpio #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output reg  [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

  // Bits 0 .. N-1 set: the pins that exist.
  localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

  localparam [3:0] IDX_DATA_OUT = 4'd0;
  localparam [3:0] IDX_DIR      = 4'd1;
  localparam [3:0] IDX_DATA_IN  = 4'd2;
  localparam [3:0] IDX_RISE     = 4'd3;
  localparam [3:0] IDX_FALL     = 4'd4;
  localparam [3:0] IDX_HIGH     = 4'd5;
  localparam [3:0] IDX_LOW      = 4'd6;
  localparam [3:0] IDX_ENABLE   = 4'd7;
  localparam [3:0] IDX_STATUS   = 4'd8;

  // State
  reg [31:0] data_out_q;
  reg [31:0] dir_q;
  reg [31:0] rise_q;
  reg [31:0] fall_q;
  reg [31:0] high_q;
  reg [31:0] low_q;
  reg [31:0] enable_q;
  reg [31:0] status_q;
  reg [31:0] in_q;
  reg [31:0] in_prev_q;

  // APB decode: zero wait states, access marks the completing cycle.
  wire        access     = psel & penable;
  wire [3:0]  idx        = paddr[5:2];
  wire        upper_zero = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
  wire        mapped     = (paddr[1:0] == 2'b00) & upper_zero & (idx <= IDX_STATUS);
  wire        wr_ok      = access & pwrite & mapped;
  wire [31:0] wmask      = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
  wire [31:0] wbits      = pwdata & wmask;

  wire we_data_out = wr_ok & (idx == IDX_DATA_OUT);
  wire we_dir      = wr_ok & (idx == IDX_DIR);
  wire we_rise     = wr_ok & (idx == IDX_RISE);
  wire we_fall     = wr_ok & (idx == IDX_FALL);
  wire we_high     = wr_ok & (idx == IDX_HIGH);
  wire we_low      = wr_ok & (idx == IDX_LOW);
  wire we_enable   = wr_ok & (idx == IDX_ENABLE);
  wire we_status   = wr_ok & (idx == IDX_STATUS);

  assign pready  = 1'b1;
  assign pslverr = access & (~mapped | (pwrite & (idx == IDX_DATA_IN)));

  // Input widened to 32 bits with zeros above N.
  wire [31:0] gpio_in_w;
  generate
    if (N < 32) begin : g_pad
      assign gpio_in_w = {{(32-N){1'b0}}, gpio_in};
    end else begin : g_full
      assign gpio_in_w = gpio_in;
    end
  endgenerate

  // Detection and status next state.
  wire [31:0] rise_ev  = in_q & ~in_prev_q;
  wire [31:0] fall_ev  = ~in_q & in_prev_q;
  wire [31:0] detected = ((rise_ev & rise_q) | (fall_ev & fall_q)
                         | (in_q & high_q) | (~in_q & low_q)) & PINS;
  wire [31:0] clear    = we_status ? wbits : 32'h0000_0000;
  wire [31:0] status_d = (status_q & ~clear) | detected;

  always @(posedge pclk) begin
    if (!presetn) begin
      data_out_q <= 32'h0000_0000;
      dir_q      <= 32'h0000_0000;
      rise_q     <= 32'h0000_0000;
      fall_q     <= 32'h0000_0000;
      high_q     <= 32'h0000_0000;
      low_q      <= 32'h0000_0000;
      enable_q   <= 32'h0000_0000;
      status_q   <= 32'h0000_0000;
      in_q       <= 32'h0000_0000;
      in_prev_q  <= 32'h0000_0000;
    end else begin
      in_q      <= gpio_in_w;
      in_prev_q <= in_q;
      status_q  <= status_d;
      if (we_data_out) data_out_q <= (data_out_q & ~wmask) | wbits;
      if (we_dir)      dir_q      <= (dir_q      & ~wmask) | wbits;
      if (we_rise)     rise_q     <= (rise_q     & ~wmask) | wbits;
      if (we_fall)     fall_q     <= (fall_q     & ~wmask) | wbits;
      if (we_high)     high_q     <= (high_q     & ~wmask) | wbits;
      if (we_low)      low_q      <= (low_q      & ~wmask) | wbits;
      if (we_enable)   enable_q   <= (enable_q   & ~wmask) | wbits;
    end
  end

  // Read multiplexer: zero unless a mapped read access.
  always @(*) begin
    prdata = 32'h0000_0000;
    if (access && !pwrite && mapped) begin
      case (idx)
        IDX_DATA_OUT: prdata = data_out_q;
        IDX_DIR:      prdata = dir_q;
        IDX_DATA_IN:  prdata = in_q;
        IDX_RISE:     prdata = rise_q;
        IDX_FALL:     prdata = fall_q;
        IDX_HIGH:     prdata = high_q;
        IDX_LOW:      prdata = low_q;
        IDX_ENABLE:   prdata = enable_q;
        IDX_STATUS:   prdata = status_q;
        default:      prdata = 32'h0000_0000;
      endcase
    end
  end

  assign gpio_out = data_out_q[N-1:0];
  assign gpio_oe  = dir_q[N-1:0];
  assign irq      = |(status_q & enable_q);

`ifdef FORMAL
  // Design-intent assertions (combinational response rules).
  always @(*) begin
    assert (pready == 1'b1);
    if (!(psel && penable)) begin
      assert (prdata == 32'h0000_0000);
      assert (pslverr == 1'b0);
    end
    if (pslverr) begin
      assert (prdata == 32'h0000_0000);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
