// Self-checking testbench for apb_gpio: N=8 and N=32 instances on one bus.
// Expected N=8 values are the N=32 expectations masked to 8 bits.
`default_nettype none

module apb_gpio_tb;

  localparam [7:0] A_DATA_OUT = 8'h00;
  localparam [7:0] A_DIR      = 8'h04;
  localparam [7:0] A_DATA_IN  = 8'h08;
  localparam [7:0] A_RISE     = 8'h0C;
  localparam [7:0] A_FALL     = 8'h10;
  localparam [7:0] A_HIGH     = 8'h14;
  localparam [7:0] A_LOW      = 8'h18;
  localparam [7:0] A_ENABLE   = 8'h1C;
  localparam [7:0] A_STATUS   = 8'h20;

  reg         pclk;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] pins;

  wire [31:0] prdata8;
  wire [31:0] prdata32;
  wire        pready8;
  wire        pready32;
  wire        pslverr8;
  wire        pslverr32;
  wire [7:0]  gpio_in8;
  wire [7:0]  gpio_out8;
  wire [7:0]  gpio_oe8;
  wire [31:0] gpio_out32;
  wire [31:0] gpio_oe32;
  wire        irq8;
  wire        irq32;

  assign gpio_in8 = pins[7:0];

  integer passed;
  integer failed;
  integer step;
  integer got_nonce;
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
    .gpio_in(gpio_in8), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8), .irq(irq8)
  );

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
    .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
    .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
    .gpio_in(pins), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32), .irq(irq32)
  );

  initial pclk = 1'b0;
  always #5 pclk = ~pclk;

  // ---------------------------------------------------------------- checks
  task chk32;
    input [31:0] got;
    input [31:0] exp;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("step %0d t=%0t: got %h expected %h", step, $time, got, exp);
      end
    end
  endtask

  task chk1;
    input got;
    input exp;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("step %0d t=%0t: got %b expected %b", step, $time, got, exp);
      end
    end
  endtask

  task chk_irq;
    input e8;
    input e32;
    begin
      chk1(irq8, e8);
      chk1(irq32, e32);
    end
  endtask

  task chk_gpio;
    input [31:0] eo;
    input [31:0] ee;
    begin
      chk32(gpio_out32, eo);
      chk32({24'h000000, gpio_out8}, eo & 32'h0000_00FF);
      chk32(gpio_oe32, ee);
      chk32({24'h000000, gpio_oe8}, ee & 32'h0000_00FF);
    end
  endtask

  task verdict;
    begin
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    end
  endtask

  // ------------------------------------------------------------ bus tasks
  // Each task starts at a falling edge and returns at a falling edge, so
  // consecutive calls are back-to-back transfers.
  task idle;
    input integer n;
    begin
      repeat (n) @(negedge pclk);
    end
  endtask

  task apb_write;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input        exp_err;
    begin
      psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
      paddr = a; pwdata = d; pstrb = s;
      #1;
      chk1(pslverr8, 1'b0);
      chk1(pslverr32, 1'b0);
      chk32(prdata8, 32'h0);
      chk32(prdata32, 32'h0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready8, 1'b1);
      chk1(pready32, 1'b1);
      chk1(pslverr8, exp_err);
      chk1(pslverr32, exp_err);
      chk32(prdata8, 32'h0);
      chk32(prdata32, 32'h0);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0;
    end
  endtask

  task apb_read;
    input [7:0]  a;
    input [31:0] e;
    input        exp_err;
    begin
      psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
      paddr = a; pwdata = 32'h0; pstrb = 4'h0;
      #1;
      chk1(pslverr8, 1'b0);
      chk1(pslverr32, 1'b0);
      chk32(prdata8, 32'h0);
      chk32(prdata32, 32'h0);
      @(negedge pclk);
      penable = 1'b1;
      #1;
      chk1(pready8, 1'b1);
      chk1(pready32, 1'b1);
      chk1(pslverr8, exp_err);
      chk1(pslverr32, exp_err);
      chk32(prdata32, e);
      chk32(prdata8, e & 32'h0000_00FF);
      @(negedge pclk);
      psel = 1'b0; penable = 1'b0;
    end
  endtask

  // kind: 0 no pin output, 1 DATA_OUT drives gpio_out, 2 DIR drives gpio_oe
  task rw_step;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input [31:0] e;
    input [1:0]  kind;
    begin
      apb_write(a, d, s, 1'b0);
      chk_gpio((kind == 2'd1) ? e : 32'h0, (kind == 2'd2) ? e : 32'h0);
      chk_irq(1'b0, 1'b0);
      apb_read(a, e, 1'b0);
    end
  endtask

  task rw_test;
    input [7:0] a;
    input [1:0] kind;
    begin
      rw_step(a, 32'hDEADBEEF, 4'hF, 32'hDEADBEEF, kind);
      rw_step(a, 32'h01234567, 4'hA, 32'h01AD45EF, kind);
      rw_step(a, 32'h00000012, 4'h1, 32'h01AD4512, kind);
      rw_step(a, 32'hFFFFFFFF, 4'h0, 32'h01AD4512, kind);
      rw_step(a, 32'h00000000, 4'hF, 32'h00000000, kind);
    end
  endtask

  task read_all;
    input [31:0] e_out;
    input [31:0] e_dir;
    input [31:0] e_in;
    input [31:0] e_rise;
    input [31:0] e_fall;
    input [31:0] e_high;
    input [31:0] e_low;
    input [31:0] e_en;
    input [31:0] e_st;
    begin
      apb_read(A_DATA_OUT, e_out,  1'b0);
      apb_read(A_DIR,      e_dir,  1'b0);
      apb_read(A_DATA_IN,  e_in,   1'b0);
      apb_read(A_RISE,     e_rise, 1'b0);
      apb_read(A_FALL,     e_fall, 1'b0);
      apb_read(A_HIGH,     e_high, 1'b0);
      apb_read(A_LOW,      e_low,  1'b0);
      apb_read(A_ENABLE,   e_en,   1'b0);
      apb_read(A_STATUS,   e_st,   1'b0);
    end
  endtask

  // ------------------------------------------------------------- watchdog
  initial begin
    #400000;
    failed = failed + 1;
    $error("timeout");
    verdict;
    $finish;
  end

  // ----------------------------------------------------------------- main
  initial begin
    passed = 0;
    failed = 0;
    step   = 0;
    nonce  = {64{8'h00}};
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);

    presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0; pins = 32'h0;

    // 1: reset
    step = 1;
    repeat (3) @(negedge pclk);
    chk_gpio(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    presetn = 1'b1;

    // 2: reset values
    step = 2;
    read_all(32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    chk_gpio(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);

    // 3: read/write registers, partial strobes, bits above N
    step = 3;
    rw_test(A_DATA_OUT, 2'd1);
    rw_test(A_DIR,      2'd2);
    rw_test(A_RISE,     2'd0);
    rw_test(A_FALL,     2'd0);
    rw_test(A_HIGH,     2'd0);
    rw_test(A_LOW,      2'd0);
    // INTR_LOW was enabled with pins low: clear whatever it set.
    apb_write(A_STATUS, 32'hFFFFFFFF, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);
    rw_test(A_ENABLE,   2'd0);

    // 4: DATA_IN is read only
    step = 4;
    pins = 32'h3C5A9617;
    apb_read(A_DATA_IN, 32'h3C5A9617, 1'b0);
    apb_write(A_DATA_IN, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_read(A_DATA_IN, 32'h3C5A9617, 1'b0);
    pins = 32'h0;
    idle(2);
    apb_read(A_DATA_IN, 32'h0, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 5: PSLVERR policy, unmapped writes change nothing, no aliasing
    step = 5;
    apb_write(A_DATA_OUT, 32'h000000C3, 4'hF, 1'b0);
    chk_gpio(32'h000000C3, 32'h0);
    apb_write(8'h01, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h02, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h03, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h0D, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h21, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h24, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h28, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h3C, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h40, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h41, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h44, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h58, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h5C, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h60, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'h9C, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'hA0, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'hFC, 32'hFFFFFFFF, 4'hF, 1'b1);
    apb_write(8'hFF, 32'hFFFFFFFF, 4'hF, 1'b1);
    chk_gpio(32'h000000C3, 32'h0);
    chk_irq(1'b0, 1'b0);
    read_all(32'h000000C3, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    apb_read(8'h01, 32'h0, 1'b1);
    apb_read(8'h02, 32'h0, 1'b1);
    apb_read(8'h03, 32'h0, 1'b1);
    apb_read(8'h21, 32'h0, 1'b1);
    apb_read(8'h24, 32'h0, 1'b1);
    apb_read(8'h3C, 32'h0, 1'b1);
    apb_read(8'h40, 32'h0, 1'b1);
    apb_read(8'h41, 32'h0, 1'b1);
    apb_read(8'h60, 32'h0, 1'b1);
    apb_read(8'h80, 32'h0, 1'b1);
    apb_read(8'h9C, 32'h0, 1'b1);
    apb_read(8'hFC, 32'h0, 1'b1);
    apb_read(8'hFF, 32'h0, 1'b1);
    apb_write(A_DATA_OUT, 32'h0, 4'hF, 1'b0);
    chk_gpio(32'h0, 32'h0);

    // 6: detection enables (INTR_ENABLE stays 0: masked conditions still set status)
    step = 6;
    apb_write(A_RISE, 32'h00100001, 4'hF, 1'b0);
    apb_write(A_FALL, 32'h00200002, 4'hF, 1'b0);
    apb_write(A_HIGH, 32'h00400004, 4'hF, 1'b0);
    apb_read(A_RISE, 32'h00100001, 1'b0);
    apb_read(A_FALL, 32'h00200002, 1'b0);
    apb_read(A_HIGH, 32'h00400004, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 7: rising edge fires once
    step = 7;
    pins = 32'h00100001;
    idle(2);
    apb_read(A_DATA_IN, 32'h00100001, 1'b0);
    apb_read(A_STATUS, 32'h00100001, 1'b0);
    chk_irq(1'b0, 1'b0);
    apb_write(A_STATUS, 32'h00100001, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);
    idle(3);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 8: falling edge fires once
    step = 8;
    pins = 32'h00300003;
    idle(2);
    apb_read(A_STATUS, 32'h0, 1'b0);
    pins = 32'h00100001;
    idle(2);
    apb_read(A_STATUS, 32'h00200002, 1'b0);
    apb_write(A_STATUS, 32'h00200002, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);
    idle(3);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 9: high level sets again after a clear
    step = 9;
    pins = 32'h00500005;
    idle(2);
    apb_read(A_STATUS, 32'h00400004, 1'b0);
    apb_write(A_STATUS, 32'h00400004, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h00400004, 1'b0);
    idle(2);
    apb_read(A_STATUS, 32'h00400004, 1'b0);
    pins = 32'h00100001;
    idle(2);
    apb_read(A_STATUS, 32'h00400004, 1'b0);
    apb_write(A_STATUS, 32'h00400004, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 10: low level sets again after a clear
    step = 10;
    pins = 32'h00900009;
    idle(2);
    apb_write(A_LOW, 32'h00800008, 4'hF, 1'b0);
    idle(2);
    apb_read(A_STATUS, 32'h0, 1'b0);
    pins = 32'h00100001;
    idle(2);
    apb_read(A_STATUS, 32'h00800008, 1'b0);
    apb_write(A_STATUS, 32'h00800008, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h00800008, 1'b0);
    pins = 32'h00900009;
    idle(2);
    apb_read(A_STATUS, 32'h00800008, 1'b0);
    apb_write(A_STATUS, 32'h00800008, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 11: write-1-to-clear of some pending bits only
    step = 11;
    pins = 32'h00800008;
    idle(2);
    pins = 32'h00900009;
    idle(2);
    pins = 32'h00B0000B;
    idle(2);
    pins = 32'h00900009;
    idle(2);
    apb_read(A_STATUS, 32'h00300003, 1'b0);
    apb_write(A_STATUS, 32'h00100002, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h00200001, 1'b0);
    apb_write(A_STATUS, 32'hFFFFFFFF, 4'h4, 1'b0);
    apb_read(A_STATUS, 32'h00000001, 1'b0);
    apb_write(A_STATUS, 32'h00000000, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h00000001, 1'b0);
    apb_write(A_STATUS, 32'hFFFFFFFE, 4'h1, 1'b0);
    apb_read(A_STATUS, 32'h00000001, 1'b0);
    apb_write(A_STATUS, 32'h00000001, 4'hE, 1'b0);
    apb_read(A_STATUS, 32'h00000001, 1'b0);
    apb_write(A_STATUS, 32'h00000001, 4'h1, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);
    chk_irq(1'b0, 1'b0);

    // 12: a detection beats a clear on the same edge
    step = 12;
    pins = 32'h00800008;
    idle(2);
    pins = 32'h00900009;
    idle(2);
    apb_read(A_STATUS, 32'h00100001, 1'b0);
    pins = 32'h00800008;
    idle(2);
    // New rising edge on pin 0 is detected on the clear's completion edge.
    pins = 32'h00900009;
    apb_write(A_STATUS, 32'h00000001, 4'h1, 1'b0);
    apb_read(A_STATUS, 32'h00100001, 1'b0);
    apb_write(A_STATUS, 32'h00100001, 4'hF, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 13: interrupt mask
    step = 13;
    pins = 32'h00800008;
    idle(2);
    pins = 32'h00900009;
    idle(2);
    apb_read(A_STATUS, 32'h00100001, 1'b0);
    chk_irq(1'b0, 1'b0);
    apb_write(A_ENABLE, 32'h00100000, 4'hF, 1'b0);
    chk_irq(1'b0, 1'b1);
    apb_write(A_ENABLE, 32'h00100001, 4'hF, 1'b0);
    chk_irq(1'b1, 1'b1);
    apb_read(A_ENABLE, 32'h00100001, 1'b0);
    apb_write(A_STATUS, 32'h00000001, 4'hF, 1'b0);
    chk_irq(1'b0, 1'b1);
    apb_read(A_STATUS, 32'h00100000, 1'b0);
    apb_write(A_STATUS, 32'h00100000, 4'hF, 1'b0);
    chk_irq(1'b0, 1'b0);

    // 14: detection latency (sample on E, status on E+1) and masking a pending bit
    step = 14;
    pins = 32'h00800008;
    idle(3);
    chk_irq(1'b0, 1'b0);
    pins = 32'h00900009;
    @(negedge pclk);
    chk_irq(1'b0, 1'b0);
    @(negedge pclk);
    chk_irq(1'b1, 1'b1);
    apb_write(A_ENABLE, 32'h0, 4'hF, 1'b0);
    chk_irq(1'b0, 1'b0);
    apb_read(A_STATUS, 32'h00100001, 1'b0);
    apb_write(A_ENABLE, 32'h00100001, 4'hF, 1'b0);
    chk_irq(1'b1, 1'b1);
    apb_write(A_STATUS, 32'hFFFFFFFF, 4'hF, 1'b0);
    chk_irq(1'b0, 1'b0);
    apb_read(A_STATUS, 32'h0, 1'b0);

    // 15: reset again with state set
    step = 15;
    apb_write(A_DATA_OUT, 32'hFFFFFFFF, 4'hF, 1'b0);
    apb_write(A_DIR, 32'h0F0F0F0F, 4'hF, 1'b0);
    chk_gpio(32'hFFFFFFFF, 32'h0F0F0F0F);
    pins = 32'h00800008;
    idle(2);
    pins = 32'h00900009;
    idle(2);
    chk_irq(1'b1, 1'b1);
    presetn = 1'b0;
    pins = 32'h00F00F0F;
    @(negedge pclk);
    chk_gpio(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);
    repeat (2) @(negedge pclk);
    presetn = 1'b1;
    read_all(32'h0, 32'h0, 32'h00F00F0F, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0, 32'h0);
    chk_gpio(32'h0, 32'h0);
    chk_irq(1'b0, 1'b0);

    verdict;
    $finish;
  end

endmodule

`default_nettype wire
